package com.jadhavr.erp.email.worker;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.jadhavr.erp.email.config.MailProperties;import com.jadhavr.erp.email.entity.EmailNotification;import com.jadhavr.erp.email.enums.EmailStatus;import com.jadhavr.erp.email.repository.EmailNotificationRepository;import com.jadhavr.erp.email.service.*;import com.jadhavr.erp.email.template.EmailTemplateRenderer;import org.springframework.scheduling.annotation.*;import org.springframework.beans.factory.annotation.Qualifier;import java.util.concurrent.Executor;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Component public class EmailWorker{private final EmailNotificationRepository repo;private final EmailProvider provider;private final MailProperties props;private final ObjectMapper json;private final TemplateDataCipher cipher;private final Executor executor;private final EmailClaimService claims;private final EmailTemplateRenderer renderer;public EmailWorker(EmailNotificationRepository r,EmailProvider p,MailProperties c,ObjectMapper j,TemplateDataCipher x,@Qualifier("emailTaskExecutor")Executor e,EmailClaimService q,EmailTemplateRenderer z){repo=r;provider=p;props=c;json=j;cipher=x;executor=e;claims=q;renderer=z;}@Scheduled(fixedDelayString="${app.mail.poll-delay-ms:10000}")public void poll(){if(!props.isEnabled())return;claims.recoverStale();for(EmailNotification n:claims.claim(props.getBatchSize()))executor.execute(()->process(n));}@Transactional protected List<EmailNotification>claim(){List<EmailNotification>x=repo.lockEligible(props.getBatchSize());x.forEach(n->{n.setStatus(EmailStatus.PROCESSING);n.setProcessingStartedAt(LocalDateTime.now());});return repo.saveAll(x);}protected void process(EmailNotification n){try{Map<String,String>d=json.readValue(cipher.decrypt(n.getTemplateData()),new TypeReference<>(){});String name=d.getOrDefault("name","User"),url=d.get("url");String text="Hello "+name+",\n\n"+n.getSubject()+(url==null?"":"\n\n"+url)+"\n\nJadhavr ERP";String html=renderer.render(n.getTemplateName(),d,n.getSubject());EmailProviderResult r=provider.send(new EmailMessage(n.getRecipientEmail(),name,n.getSubject(),html,text));sent(n,r);}catch(Exception e){failed(n,e);}}@Transactional protected void sent(EmailNotification n,EmailProviderResult r){n.setStatus(EmailStatus.SENT);n.setProvider("SMTP");n.setProviderMessageId(r.providerMessageId());n.setSentAt(LocalDateTime.now());n.setFailureReason(null);repo.save(n);}@Transactional protected void failed(EmailNotification n,Exception e){int count=n.getRetryCount()+1;n.setRetryCount(count);n.setFailureReason("Email delivery failed");if(count>=n.getMaxRetries())n.setStatus(EmailStatus.FAILED);else{n.setStatus(EmailStatus.RETRY_PENDING);long delay=(long)props.getRetryDelaySeconds()*(1L<<Math.min(count-1,4))+new Random().nextInt(15);n.setNextRetryAt(LocalDateTime.now().plusSeconds(delay));}repo.save(n);}private String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace("'","&#39;");}}




